import{_ as p,o,c as n,a5 as e}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"类和对象","description":"","frontmatter":{"title":"类和对象","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","面向对象","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第二部分：面向对象/01-类与对象/类和对象/类和对象.md","filePath":"posts/java快速入门/第二部分：面向对象/01-类与对象/类和对象/类和对象.md"}'),s={name:"posts/java快速入门/第二部分：面向对象/01-类与对象/类和对象/类和对象.md"};function r(u,t,c,d,a,g){return o(),n("div",null,[...t[0]||(t[0]=[e('<div><p><strong>类</strong>：是一组相关<strong>属性</strong>和<strong>行为</strong>的集合，使用事物的属性特征和行为特征来描述该类事物， <strong>可以看成是一类事物的模板。</strong></p><p>现实中，描述一类事物： <strong>属性</strong>：就是该事物的状态信息。 <strong>行为</strong>：就是该事物能够做什么。 举例：小猫。 属性：名字、体重、年龄、颜色。 行为：走、跑、叫。</p><p><strong>对象</strong>：是一类事物的具体体现。对象是类的一个<strong>实例</strong>，必然具备该类事物的属性和行为。 现实中，一类事物的一个实例：一只小猫。 举例：一只小猫。 属性：<code>tom</code>、<code>5kg</code>、<code>2 years</code>、<code>yellow</code>。 行为：溜墙根走、蹦跶的跑、喵喵叫。</p><p><strong>类与对象的关系</strong> 类是对一类事物的描述，是<strong>抽象的</strong>。 对象是一类事物的实例，是<strong>具体的</strong>。</p><p><code>Java</code>中用<code>class</code>描述事物也是如此： <strong>成员变量</strong>：对应事物的<strong>属性</strong><strong>成员方法</strong>：对应事物的<strong>行为</strong></p><p><strong>类的定义格式</strong></p><p>public class ClassName { // 成员变量</p><p>// 成员方法</p><p>} <strong>定义类</strong>：就是定义类的成员，包括<strong>成员变量</strong>和<strong>成员方法</strong>。 <strong>成员变量</strong>：和以前定义变量几乎是一样的。只不过位置发生了改变。<strong>在类中，方法外</strong>。 <strong>成员方法</strong>：和以前定义方法几乎是一样的。 类的定义格式举例：</p><p>public class Student { // 成员变量</p><p><code>String name</code></p><p>；<code>//</code>姓名</p><p><code>int age</code></p><p>；<code>//</code>年龄</p><p>// 成员方法</p><p>// 学习的方法</p><p>publicvoid study() { System.out.println(&quot; 好好学习，天天向上</p><p>&quot;); } // 吃饭的方法</p><p>publicvoid eat() { System.out.println(&quot; 学习饿了要吃饭</p><p>&quot;); } } <strong>对象的使用</strong> 创建对象： 类名 对象名</p><p><code>= new</code></p><p>类名<code>();</code> 使用对象访问类中的成员<code>:</code></p><ul><li>对象名<code>.</code>成员变量；</li><li>对象名<code>.</code>成员方法<code>()</code>；</li></ul><p>对象的使用格式举例</p><p>: public class Test01_Student { public static void main(String[] args) { // 创建对象格式：类名 对象名 <code>= new</code> 类名</p><p>(); Student s = new Student(); System.out.println(&quot;s:&quot;+s); <a href="//cn.itcast.Student" target="_blank" rel="noreferrer">//cn.itcast.Student</a>@100363 // 直接输出成员变量值</p><p>System.out.println(&quot; 姓名：</p><p>&quot;+s.name); //null System.out.println(&quot; 年龄：</p><p>&quot;+s.age); //0 System.out.println(&quot; ‐‐‐‐‐‐‐‐‐‐</p><p>&quot;); // 给成员变量赋值</p><p><code>s.name = &quot;</code></p><p>赵丽颖</p><p>&quot;; s.age = 18; // 再次输出成员变量的值</p><p>System.out.println(&quot; 姓名：</p><p>&quot;+s.name); // 赵丽颖</p><p>System.out.println(&quot; 年龄：</p><p>&quot;+s.age); //18 System.out.println(&quot; ‐‐‐‐‐‐‐‐‐‐</p><p>&quot;); // 调用成员方法</p><p>s.study(); // &quot; 好好学习，天天向上</p><p>&quot; s.eat(); // &quot; 学习饿了要吃饭</p><p>&quot; } }</p><p><strong>成员变量的默认值</strong></p><p><strong>类与对象的练习</strong> 定义手机类： 定义测试类：</p><p>public class Phone { // 成员变量</p><p>String brand; // 品牌</p><p>int price; // 价格</p><p>String color; // 颜色</p><p>// 成员方法</p><p>// 打电话</p><p>public void call(String name) { System.out.println(&quot; 给</p><p><code>&quot;+name+&quot;</code></p><p>打电话</p><p>&quot;); } // 发短信</p><p>public void sendMessage() { System.out.println(&quot; 群发短信</p><p>&quot;); } }</p><p>public class Test02Phone { public static void main(String[] args) { // 创建对象</p><p>Phone p = new Phone(); // 输出成员变量值</p><p>System.out.println(&quot; 品牌：</p><p>&quot;+p.brand);//null System.out.println(&quot; 价格：</p><p>&quot;+p.price);//0 System.out.println(&quot; 颜色：</p><p>&quot;+p.color);//null System.out.println(&quot; ‐‐‐‐‐‐‐‐‐‐‐‐</p><p>&quot;);// 给成员变量赋值</p><p><code>p.brand = &quot;</code></p><p>锤子</p><p>&quot;; p.price = 2999; p.color = &quot; 棕色</p><p>&quot;; // 再次输出成员变量值</p><p>System.out.println(&quot; 品牌：</p><p>&quot;+p.brand);// 锤子</p><p>System.out.println(&quot; 价格：</p><p>&quot;+p.price);//2999 System.out.println(&quot; 颜色：</p><p>&quot;+p.color);// 棕色</p><p>System.out.println(&quot; ‐‐‐‐‐‐‐‐‐‐‐‐</p><p>&quot;); // 调用成员方法</p><p><code>p.call(&quot;</code></p><p>紫霞</p><p>&quot;); p.sendMessage(); } } <strong>对象内存图</strong><strong>一个对象，调用一个方法内存图</strong></p><p>通过上图，我们可以理解，在栈内存中运行的方法，遵循<code>&quot;</code>先进后出，后进先出<code>&quot;</code>的原则。 变量<code>p</code>指向堆内存中的空间，寻找方法信息，去执行该方法。</p><p>但是，这里依然有问题存在。创建多个对象时，如果每个对象内部都保存一份方法信息，这就非常浪费内存了，因为所有对象的方法信息都是一样的。那么如何解决这个问题呢？请看如下图解。</p><p><strong>两个对象，调用同一方法内存图</strong></p><p>对象调用方法时，根据对象中方法标记（地址值），去类中寻找方法信息。这样哪怕是多个对象，方法信息只保存一份，节约内存空间。</p><p><strong>一个引用，作为参数传递到方法中内存图</strong></p><p>引用类型作为参数，传递的是地址值。</p><p><strong>成员变量和局部变量区别</strong> 变量根据定义<strong>位置的不同</strong>，我们给变量起了不同的名字。</p><p>位置不同： 成员变量：类中，方法外 局部变量：方法中或者方法声明上<code>(</code>形式参数<code>)</code></p><p>作用范围不一样： 成员变量：类中 局部变量：方法中</p><p>初始化值的不同： 成员变量：有默认值 局部变量：没有默认值。必须先定义，赋值，最后使用</p><p>在内存中的位置不同： 成员变量：堆内存 局部变量：栈内存</p><p>生命周期不同 了解 成员变量：随着对象的创建而存在，随着对象的消失而消失 局部变量：随着方法的调用而存在，随着方法的调用完毕而消失</p></div>',1)])])}const q=p(s,[["render",r]]);export{l as __pageData,q as default};
